with target as (
  select slug from venues where slug = 'honey-and-smoke' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Shared Dining', 1, 'draft', 'partial', 'https://honeyandsmoke.co/menus/shared-dining', 'Official Honey & Smoke menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, 'f1a702914d9866f58588eaf629b02f3e5945dc4d9aeee14830abee17b727a176', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Breads & Dips', 0)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Breads & Dips', 'TURKISH FLAT BREAD', 'cooked over fire coals / finished with za''atar salt', 55000, 'IDR', 0), ('Breads & Dips', 'GRILLED SOURDOUGH BREAD', 'rosemary / parmesan / house smoked lardo', 85000, 'IDR', 1), ('Breads & Dips', 'WHIPPED CHICKPEA HUMMUS', 'falafel / green olive / parsley', 95000, 'IDR', 2), ('Breads & Dips', 'SPINACH BORANI', 'Turkish flat bread / house olive', 175000, 'IDR', 3), ('Breads & Dips', 'MEZZE PLATE', 'homemade pickles / dolma / cucumber tzatziki / green olive hummus / harissa babaganoush / puffed Lebanese bread', 185000, 'IDR', 4)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

