join (values ('Eucalyptus Signature', 'Pramana Journey (120 Minutes)', 'Ideal for those with poor sleep patterns. It starts with a 90 minutes deep tissue massage along with body stretching will give a gentle touch to stimulate blood circulation to relax your body and mind. The spa journey end with citrus and fresh milk bath.', 795000, 'IDR', 0), ('Eucalyptus Signature', 'Eucalyptus Sensation (90 Minutes)', 'Celebrate your special day by experiencing a warm sensation signature of Eucalyptus treatment. Immerse in the warmth of eucalyptus essential oil and rejuvenate after the refreshing facial.', 815000, 'IDR', 1), ('Body Massage', 'Balinese Massage (60 Minutes)', 'Authentic traditional Massage its combined with Balinese technique, long stroke skin rolling, palm, thumbs pressure techniques to balance the energy centers and improve the integration of your internal systems, blood circulation and release stress.', 399000, 'IDR', 0), ('Body Massage', 'Balinese Massage (90 Minutes)', 'Authentic traditional Massage its combined with Balinese technique, long stroke skin rolling, palm, thumbs pressure techniques to balance the energy centers and improve the integration of your internal systems, blood circulation and release stress.', 585000, 'IDR', 1), ('Body Massage', 'Body Scrub (60 Minutes)', 'A special exfoliation treatment using natural turmeric scrub to detoxify your skin, leaving it smooth and shiny. Included in the treatment: natural foot bath, body scrub, milk bath or bubble bath, and moisturizing lotion.', 445000, 'IDR', 2), ('Body Massage', 'Back Massage (60 Minutes)', 'This is the perfect cure after long flights, to relieve tensions. It consists of a condensed but complete head, neck and shoulder massage using our special blend of oils. Head, neck, and shoulder massage', 359000, 'IDR', 3), ('Body Massage', 'Aromatherapy Massage (60 Minutes)', null, 445000, 'IDR', 4), ('Body Massage', 'Aromatherapy Massage (90 Minutes)', 'Experience our signature massage that offer a warm sense of cajuput essential oil in very gentle bit firm strokes depending on your preference. Effective to reduce stress, rejuvenate your body and revitalize your body.', 545000, 'IDR', 5), ('Body Massage', 'Deep Tissue Massage (60 Minutes)', null, 465000, 'IDR', 6), ('Body Massage', 'Deep Tissue Massage (90 Minutes)', 'A Healing massage using fingers, palm, shiatsu technique, Balinese massage, and elbow flowing with concentrated energy for long continuous strokes combined with stretching & gentle touch. Provides a completes relaxation and relieves tension.', 535000, 'IDR', 7), ('Body Massage', 'Zhiatsu Massage (60 Minutes)', null, 425000, 'IDR', 8), ('Body Massage', 'Zhiatsu Massage (90 Minutes)', 'A therapeutic dry massage performed without massage oil, using finger, thumb, palm, and elbow pressure applied to specific energy points throughout the body. Combined with gentle stretching and rhythmic movements, this treatment helps stimulate the body’s natural energy flow, relieve muscle tension, improve circulation, reduce fatigue, and restore physical and mental balance. Ideal for guests seek', 515000, 'IDR', 9), ('Body Massage', 'Warm Oil Massage (60 Minutes)', null, 465000, 'IDR', 10), ('Body Massage', 'Warm Oil Massage (90 Minutes)', 'An Exclusive Balinese Massage combined with heated coconut oil to warm the body. The combination of acupressure and hot oil will help to balance your energy, loosen tight muscle and improve blood circulation.', 535000, 'IDR', 11), ('Body Massage', 'Herbal Poultice (90 Minutes)', 'Herbal Poultice Massage is a deep heat medicinal muscle therapeutic treatment. This massage dates back to the 14th century and consists of a warm herbal compress filled with organic herbs directly to the body in various specialized techniques. It relaxes and soothes tense muscles, eases aches, pains and injuries.', 895000, 'IDR', 12), ('Body Massage', 'Warm Stone Relaxation Massage (90 Minutes)', 'Healing therapy by using smooth-heated volcanic stones applied to scattered points on the body to warm tight muscles and open blockages to improve blood circulation. The treatment will help you to relax, revitalize your body, reduce back pain, and even cure colds.', 599000, 'IDR', 13), ('Foot Treatment', 'Foot Massage (60 Minutes)', 'It is an application of appropriate pressure to areas on the feet and lower legs, muscle and reflex points that correspond to different organs and systems. This treatment is perfect to release stress and ease tensions.', 359000, 'IDR', 0), ('Foot Treatment', 'Foot Reflexology (60 Minutes)', 'An ancient Chinese healing art focused on the pressure point in the feet that correspond with organs and muscles of body to improve circulation and general wellness. The pressure technique is to balance the energy centers and improve the integration of your internal systems, blood circulation and stress release.', 425000, 'IDR', 1), ('Beauty', 'Natural Facial (60 Minutes)', 'With natural blended ingredients to nourish, balance and control. The natural facial combined with luxurious techniques and eucalyptus spa pressure point style to ease tension in the skin leaving it gently cleansed, polish and glowing like sunshine and inner beauty.', 459000, 'IDR', 0), ('Beauty', 'Organic Facial (60 Minutes)', 'Using organic sensation products, this facial is designed to nourish your skin by fresh carrot, cucumber, and yogurt which combined with luxurious techniques and eucalyptus spa pressure point style to ease tension and indulge your skin naturally.', 459000, 'IDR', 1), ('Spa Package', 'Recharging Package (120 Minutes)', 'A combination of some selected treatments to offer you a memorable experience of a body and mind rejuvenation ritual. Each treatment is chosen thoughtfully which provides continuum relaxation from one treatment to another. This package includes foot ritual, Balinese massage, natural turmeric scrub, milk bath or bubble bath, and moisturizing body lotion.', 735000, 'IDR', 0), ('Spa Package', 'Refreshing Package (120 Minutes)', 'Celebrate your special day by experiencing a unique sensation of the combination treatment. Immerse in the warmth essential oil and rejuvenate after the refreshing facial. This package includes foot ritual, Balinese massage and Natural Facial.', 735000, 'IDR', 1)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

