join (values ('Massages', 'Deep Tissue – Karsa Spa’s signature massage', 'A thorough massage based on Chinese acupressure points to release stress and blockages from the tips of your toes to the top of your head. It helps to loosen muscle tissues, release toxins from muscles and get blood and oxygen circulating properly. Our deep tissue massage is beneficial for many physical problems, including sports injuries and chronic pain.', 260000, 'IDR', 0), ('Massages', 'Traditional Balinese', 'Traditional Balinese techniques that include long strokes and light acupressure stimulation. Releases muscle tension, improves blood circulation and dissolves stress.', 240000, 'IDR', 1), ('Massages', 'Intuitive Heart Massage', 'Your massage begins with Reiki which opens your aura and chakras to receive divine healing energy throughout your treatment. Your massage flows seamlessly as your therapist tunes into your body and hones into areas that require extra attention.', 400000, 'IDR', 2), ('Massages', 'Shiatsu Treatment', 'A massage based on ancient Japanese healing systems to release muscle and meridian blockages which may cause pain physically, mentally and emotionally.', 280000, 'IDR', 3), ('Massages', 'Therapeutic / Sports Massage', 'This massage is with an experienced male therapist for injuries or long-term problems that you just can’t seem to shift.', 450000, 'IDR', 4), ('Massages', 'Foot Reflexology', 'Acupressure points on your feet correspond with body organs and parts of your body. When stimulated many blockages are released and dissolved.', 140000, 'IDR', 5), ('Massages', 'Thai Yoga Massage', 'A gentle form of Thai massage uses slow rhythmic movements to release blockages from the sen (meridian lines). This is a beautiful and deeply relaxing experience.', 450000, 'IDR', 6), ('Massages', 'Back Neck Shoulder Massage', 'A deep tissue massage focused on the back, neck, and shoulders for those in a hurry or who need more targeted relief.', 150000, 'IDR', 7), ('Massages', 'Anak Anak Kids Massage', 'A lovely introduction to bodywork for your wriggling, giggling little ones.', 140000, 'IDR', 8), ('Massages', 'Baby on Board Pregnancy Massage', 'Massage at an angle, according to your individual needs. You can choose to be sitting in a chair or lying on a table.', 240000, 'IDR', 9), ('Massages', 'Singing Bowl Healing Vibration', 'This treatment can be deeply healing and soothing. If you have any specific back or shoulder problems please tell your therapist who will add warm water into the bowl which enhances your treatment.', 140000, 'IDR', 10), ('Massages', 'Chinese Cupping', 'Cupping involves placing modern silicone cups on the skin and creating a vacuum by suctioning out the air. Cupping can loosen muscles, encourage blood flow, and sedate the nervous system.', 140000, 'IDR', 11)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

